package os.aios.core.workspace;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;

/** Rebuildable external-resource catalog, physically separate from personal memory. */
final class ContextStore extends SQLiteOpenHelper{
 ContextStore(WorkspaceStore owner){super(owner.appContext(),owner.contextDatabase(),null,1);setWriteAheadLoggingEnabled(true);}
 public void onConfigure(SQLiteDatabase d){d.setForeignKeyConstraintsEnabled(true);}
 public void onCreate(SQLiteDatabase d){
  d.execSQL("CREATE TABLE resources(id TEXT PRIMARY KEY,uri TEXT NOT NULL,kind TEXT NOT NULL,version TEXT NOT NULL,permission_scope TEXT NOT NULL,trust TEXT NOT NULL,availability TEXT NOT NULL CHECK(availability IN ('available','temporarily_unavailable','deleted','revoked')),mime TEXT NOT NULL DEFAULT '',metadata TEXT NOT NULL DEFAULT '{}',updated_at INTEGER NOT NULL)");
  d.execSQL("CREATE TABLE fragments(id TEXT PRIMARY KEY,resource_id TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE,resource_version TEXT NOT NULL,processor_id TEXT NOT NULL,processor_version TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('original','transcript','ocr','summary','embedding')),locator TEXT NOT NULL,text TEXT NOT NULL,complete INTEGER NOT NULL,generation INTEGER NOT NULL,updated_at INTEGER NOT NULL)");
  d.execSQL("CREATE INDEX fragments_resource ON fragments(resource_id,resource_version,generation)");
  d.execSQL("CREATE INDEX fragments_text ON fragments(text)");
  d.execSQL("CREATE TABLE processing_intents(id TEXT PRIMARY KEY,resource_id TEXT NOT NULL,resource_version TEXT NOT NULL,processor_id TEXT NOT NULL,state TEXT NOT NULL,generation INTEGER NOT NULL,lease_until INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL,UNIQUE(resource_id,resource_version,processor_id))");
 }
 public void onUpgrade(SQLiteDatabase d,int a,int b){throw new IllegalStateException("Unsupported Context schema upgrade");}
 synchronized JSONObject call(String op,JSONObject p)throws Exception{SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{JSONObject r=execute(d,op,p);d.setTransactionSuccessful();return r;}finally{d.endTransaction();}}
 private JSONObject execute(SQLiteDatabase d,String op,JSONObject p)throws Exception{
  if(op.equals("context.resource.upsert")){String id=p.getString("id"),version=p.getString("version"),trust=p.optString("trust","external_untrusted");os.aios.runtime.CoreContracts.Trust.valueOf(trust.toUpperCase(Locale.ROOT));ContentValues v=new ContentValues();v.put("id",id);v.put("uri",p.getString("uri"));v.put("kind",p.getString("kind"));v.put("version",version);v.put("permission_scope",p.getString("permission_scope"));v.put("trust",trust);v.put("availability","available");v.put("mime",p.optString("mime"));v.put("metadata",p.optJSONObject("metadata")==null?"{}":p.getJSONObject("metadata").toString());v.put("updated_at",WorkspaceStore.now());JSONObject old=one(d,"SELECT * FROM resources WHERE id=?",id);d.insertWithOnConflict("resources",null,v,SQLiteDatabase.CONFLICT_REPLACE);if(old!=null&&!old.getString("version").equals(version))d.delete("fragments","resource_id=? AND resource_version<>?",new String[]{id,version});return one(d,"SELECT * FROM resources WHERE id=?",id);}
  if(op.equals("context.resource.invalidate")){String state=p.getString("availability");if(!Set.of("temporarily_unavailable","deleted","revoked").contains(state))throw new IllegalArgumentException("Invalid availability");d.execSQL("UPDATE resources SET availability=?,updated_at=? WHERE id=? AND version=?",new Object[]{state,WorkspaceStore.now(),p.getString("id"),p.getString("expected_version")});if(d.compileStatement("SELECT changes()").simpleQueryForLong()!=1)throw new IllegalStateException("Resource version changed");if(!state.equals("temporarily_unavailable"))d.delete("fragments","resource_id=?",new String[]{p.getString("id")});return new JSONObject().put("id",p.getString("id")).put("availability",state);}
  if(op.equals("context.fragment.put")){JSONObject resource=required(d,"resources",p.getString("resource_id"));if(!resource.getString("availability").equals("available")||!resource.getString("version").equals(p.getString("resource_version")))throw new IllegalStateException("Source version unavailable");String kind=p.getString("kind");if(!Set.of("original","transcript","ocr","summary","embedding").contains(kind))throw new IllegalArgumentException("Invalid fragment kind");String text=p.optString("text","");if(text.length()>262144)throw new IllegalArgumentException("Fragment exceeds 256 KiB");ContentValues v=new ContentValues();v.put("id",p.getString("id"));v.put("resource_id",resource.getString("id"));v.put("resource_version",resource.getString("version"));v.put("processor_id",p.getString("processor_id"));v.put("processor_version",p.getString("processor_version"));v.put("kind",kind);v.put("locator",p.getString("locator"));v.put("text",text);v.put("complete",p.optBoolean("complete",true)?1:0);v.put("generation",p.getLong("generation"));v.put("updated_at",WorkspaceStore.now());d.insertWithOnConflict("fragments",null,v,SQLiteDatabase.CONFLICT_REPLACE);return required(d,"fragments",p.getString("id"));}
  if(op.equals("context.search")){String q=p.optString("query","").trim(),scope=p.getString("permission_scope");int limit=Math.max(1,Math.min(100,p.optInt("limit",20)));JSONArray rows=new JSONArray();try(Cursor c=d.rawQuery("SELECT f.*,r.uri,r.mime,r.trust,r.permission_scope FROM fragments f JOIN resources r ON r.id=f.resource_id WHERE r.availability='available' AND r.version=f.resource_version AND r.permission_scope=? AND f.complete=1 AND (?='' OR instr(lower(f.text),lower(?))>0) ORDER BY f.updated_at DESC LIMIT ?",new String[]{scope,q,q,Integer.toString(limit)})){while(c.moveToNext())rows.put(row(c));}return new JSONObject().put("items",rows).put("engine","exact_substring_baseline").put("semantic_supported",false);}
  if(op.equals("context.resource.get"))return required(d,"resources",p.getString("id"));throw new IllegalArgumentException("Unknown context action");
 }
 private JSONObject required(SQLiteDatabase d,String table,String id)throws Exception{JSONObject o=one(d,"SELECT * FROM "+table+" WHERE id=?",id);if(o==null)throw new IllegalArgumentException("Record not found: "+id);return o;}
 private JSONObject one(SQLiteDatabase d,String sql,String id)throws Exception{try(Cursor c=d.rawQuery(sql,new String[]{id})){return c.moveToFirst()?row(c):null;}}
 private JSONObject row(Cursor c)throws Exception{JSONObject o=new JSONObject();for(int i=0;i<c.getColumnCount();i++)o.put(c.getColumnName(i),c.isNull(i)?JSONObject.NULL:c.getType(i)==Cursor.FIELD_TYPE_INTEGER?c.getLong(i):c.getString(i));return o;}
}
